"""Self-contained local UI for the first executable project/data slice."""
HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NeuralForge</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#172033;background:#f3f6fb}*{box-sizing:border-box}body{margin:0}.top{background:#101a31;color:#fff;padding:18px 28px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:800;font-size:20px;letter-spacing:.2px}.brand span{color:#7bd9c5}.wrap{max-width:1100px;margin:32px auto;padding:0 20px}.intro{margin-bottom:22px}.intro h1{margin:0 0 6px;font-size:28px}.muted{color:#627086}.grid{display:grid;grid-template-columns:340px 1fr;gap:18px}.card{background:white;border:1px solid #e0e6ef;border-radius:12px;padding:20px;box-shadow:0 4px 16px #16233d08}.card h2{font-size:17px;margin:0 0 16px}.field{display:block;margin:12px 0}.field span{display:block;font-size:13px;font-weight:650;margin-bottom:6px}input,select,textarea{width:100%;border:1px solid #cbd5e1;border-radius:7px;padding:10px;font:inherit;background:white}button{border:0;border-radius:7px;background:#176b62;color:white;padding:10px 14px;font-weight:700;cursor:pointer}button.secondary{background:#e7f3f1;color:#145e56}button.danger{background:#b42318}button:disabled{opacity:.5;cursor:wait}.project{padding:13px;border:1px solid #e4e9f0;border-radius:8px;margin:8px 0;cursor:pointer}.project.active{border-color:#168477;background:#f1fbf8}.project strong{display:block}.tag{font-size:12px;color:#526178}.row{display:flex;justify-content:space-between;align-items:center;gap:10px}.upload{border:1px dashed #9baabd;border-radius:8px;padding:14px;margin:12px 0}.table{width:100%;border-collapse:collapse;margin-top:10px;font-size:13px}.table th,.table td{text-align:left;padding:9px;border-bottom:1px solid #edf0f4;vertical-align:top}.pill{display:inline-block;background:#e9f5f2;color:#126157;padding:3px 8px;border-radius:20px;font-size:12px}.notice{padding:11px;border-radius:7px;background:#fff7e6;color:#795500;margin:10px 0}.error{padding:11px;border-radius:7px;background:#fff0ee;color:#9c261c;margin:10px 0}.empty{color:#78869a;padding:20px;text-align:center}.small{font-size:12px}.hidden{display:none}@media(max-width:760px){.grid{grid-template-columns:1fr}.top{padding:15px}.wrap{margin-top:20px}}
</style></head><body><header class="top"><div class="brand">Neural<span>Forge</span></div><div class="small">Local workspace · data stays on this machine</div></header>
<main class="wrap"><section id="auth-panel" class="card" style="max-width:430px;margin:50px auto"><h1>NeuralForge account</h1><p class="muted">Register an account or sign in to access your private projects.</p><div id="auth-message"></div><form id="auth-form"><label class="field"><span>Username</span><input name="username" required minlength="3" maxlength="64" autocomplete="username"></label><label class="field"><span>Password</span><input name="password" type="password" required minlength="12" maxlength="256" autocomplete="current-password"></label><button type="submit" id="auth-submit">Sign in</button> <button type="button" class="secondary" id="register-toggle">Create account</button></form><p class="small muted">The first registered account becomes the local administrator. Use a unique 12+ character password.</p></section><div id="app-content" class="hidden"><section class="intro"><h1>Build a machine-learning project</h1><div class="muted">Create a project, inspect a dataset, and continue through the lifecycle as capabilities are implemented.</div></section>
<div id="message"></div><section class="grid"><div class="card"><details id="admin-global" class="hidden"><summary>Administration · global configuration</summary><label class="field"><span>Application name</span><input id="global-cfg-name" value="NeuralForge"></label><label class="field"><span>Maximum upload size (MiB; 1–100)</span><input id="global-cfg-upload" type="number" min="1" max="100" value="100"></label><label class="field"><input type="checkbox" id="global-cfg-registration" style="width:auto"> Allow new registrations</label><button id="global-cfg-save">Save settings</button></details><h2>New project</h2><form id="create"><label class="field"><span>Project name</span><input name="name" maxlength="80" required placeholder="e.g. Customer churn"></label><label class="field"><span>Task</span><select name="task_type"><option value="tabular_classification">Tabular classification</option><option value="tabular_regression">Tabular regression</option><option value="text_classification">Text classification</option></select></label><label class="field"><span>Description (optional)</span><textarea name="description" maxlength="500" rows="3"></textarea></label><button>Create project</button></form><hr style="border:0;border-top:1px solid #edf0f4;margin:20px 0"><div class="row"><h2 style="margin:0">Projects</h2><button class="secondary" id="refresh">Refresh</button></div><div id="projects" class="empty">Loading projects…</div></div>
<div class="card"><div class="row"><div><h2 id="detail-title" style="margin-bottom:4px">Select a project</h2><div id="detail-sub" class="muted small">Your datasets and lifecycle resources will appear here.</div></div><span class="pill">Local</span></div><div id="workspace" class="empty">Create or select a project to get started.</div></div></section></div>
</main><script>
const $=s=>document.querySelector(s);let selected=null,activeProject=null,currentUser=null,registerMode=false;
function msg(text,error=false){$('#message').innerHTML=text?`<div class="${error?'error':'notice'}">${escapeHtml(text)}</div>`:''}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function api(url,options={}){const r=await fetch(url,options);const j=await r.json();if(!r.ok)throw Error(j.error?.message||'Request failed');return j}
async function loadProjects(){try{const {projects}=await api('/api/projects');const box=$('#projects');if(!projects.length){box.innerHTML='<div class="empty">No projects yet.</div>';return}box.innerHTML=projects.map(p=>`<div class="project ${selected===p.id?'active':''}" data-id="${escapeHtml(p.id)}"><div class="row"><strong>${escapeHtml(p.name)}</strong>${p.can_manage?`<button class="danger small delete" data-id="${escapeHtml(p.id)}">Delete</button>`:''}</div><div class="tag">${escapeHtml(p.task_type.replaceAll('_',' '))}</div></div>`).join('');box.querySelectorAll('.project').forEach(el=>el.addEventListener('click',e=>{if(!e.target.closest('.delete'))selectProject(el.dataset.id)}));box.querySelectorAll('.delete').forEach(b=>b.addEventListener('click',async e=>{e.stopPropagation();if(confirm('Delete this project and its stored datasets?'))try{await api('/api/projects/'+b.dataset.id,{method:'DELETE'});if(selected===b.dataset.id){selected=null;$('#workspace').innerHTML='Create or select a project to get started.'}loadProjects()}catch(err){msg(err.message,true)}}));}catch(e){msg(e.message,true)}}
async function selectProject(id){selected=id;await loadProjects();const {projects}=await api('/api/projects');const p=projects.find(x=>x.id===id);if(!p)return;activeProject=p;$('#detail-title').textContent=p.name;$('#detail-sub').textContent=p.description||p.task_type.replaceAll('_',' ');renderWorkspace();loadDatasets()}
function renderWorkspace(){if(!selected)return;$('#workspace').innerHTML=`<h3>Data</h3><details><summary>Change account password</summary><label class="field"><span>Current password</span><input type="password" id="current-password" autocomplete="current-password"></label><label class="field"><span>New password (12 characters minimum)</span><input type="password" id="new-password" autocomplete="new-password"></label><button id="change-password" class="secondary">Update password</button></details><p class="muted">Upload a UTF-8 CSV to calculate a local schema/profile. Project data is private to its owner unless explicitly shared.</p>${activeProject?.can_manage?`<details><summary>Share project</summary><div class="row"><input id="share-user" placeholder="Username to share with"><select id="share-role"><option value="viewer">Viewer</option><option value="editor">Editor</option></select><button id="share-button" class="secondary">Share</button></div></details>`:''}${activeProject?.can_write?`<div class="upload"><label class="field"><span>CSV file</span><input id="csvfile" type="file" accept=".csv,text/csv"></label><button id="upload">Upload and profile</button></div>`:'<p class="notice">You have read-only access to this shared project.</p>'}<div id="datasets"><div class="empty">No dataset selected.</div></div><hr style="border:0;border-top:1px solid #edf0f4;margin:20px 0"><h3>Lifecycle</h3><p class="muted">Data profiling is the first working slice. Pipeline preparation, model design, training, evaluation, deployment, and monitoring will be added as real connected workflows—not simulated controls.</p>`;const uploadButton=$('#upload');if(uploadButton)uploadButton.onclick=upload;$('#change-password').onclick=async()=>{try{await api('/api/auth/password/change',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_password:$('#current-password').value,new_password:$('#new-password').value})});alert('Password changed. Please sign in again.');location.reload()}catch(e){msg(e.message,true)}};const share=$('#share-button');if(share)share.onclick=async()=>{try{await api(`/api/projects/${selected}/share`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#share-user').value,role:$('#share-role').value})});msg('Project shared.')}catch(e){msg(e.message,true)}};}
async function upload(){const f=$('#csvfile').files[0];if(!f)return msg('Choose a CSV file first.',true);const b=$('#upload');b.disabled=true;b.textContent='Uploading…';try{const result=await api(`/api/projects/${selected}/datasets?filename=${encodeURIComponent(f.name)}`,{method:'POST',headers:{'Content-Type':'text/csv'},body:f});msg(`Profiled ${result.dataset.row_count.toLocaleString()} rows and ${result.dataset.column_count} columns.`);loadDatasets()}catch(e){msg(e.message,true)}finally{b.disabled=false;b.textContent='Upload and profile'}}
async function loadDatasets(){if(!selected)return;try{const {datasets}=await api(`/api/projects/${selected}/datasets`);const el=$('#datasets');if(!datasets.length){el.innerHTML='<div class="empty">No datasets uploaded yet.</div>';return}el.innerHTML=datasets.map(d=>`<div class="row"><h3>${escapeHtml(d.filename)}</h3><span class="pill">${d.row_count.toLocaleString()} rows · ${d.column_count} columns</span></div><p class="muted small">${d.duplicate_rows} duplicate rows detected. Inferred types and top values are descriptive heuristics.</p><div style="overflow:auto"><table class="table"><thead><tr><th>Column</th><th>Type</th><th>Missing</th><th>Unique</th><th>Sample / summary</th></tr></thead><tbody>${d.columns.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${escapeHtml(c.inferred_type)}</td><td>${c.missing}</td><td>${c.unique}</td><td>${escapeHtml(c.inferred_type==='numeric'?(c.numeric?`min ${c.numeric.min}; mean ${c.numeric.mean.toFixed(3)}; max ${c.numeric.max}`:''):c.sample_values.join(', '))}</td></tr>`).join('')}</tbody></table></div><h3>Train a real local neural-network model</h3><p class="muted small">CPU training using scikit-learn MLP; one 80/20 train/validation split. This is an initial tabular training implementation, not a production framework adapter.</p><label class="field"><span>Target column</span><select id="target-${d.dataset_id}">${d.columns.map(c=>`<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)} (${escapeHtml(c.inferred_type)})</option>`).join('')}</select></label><label class="field"><span>Text input column (used only for text classification)</span><select id="text-${d.dataset_id}">${d.columns.filter(c=>c.inferred_type==='categorical').map(c=>`<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}</option>`).join('')}</select></label><button class="train" data-id="${d.dataset_id}">Start training</button><div class="run-result" id="run-${d.dataset_id}"></div>`).join('');el.querySelectorAll('.train').forEach(button=>{if(!activeProject?.can_write){button.disabled=true;button.textContent='Read only'}else button.onclick=()=>startTraining(button.dataset.id)})}catch(e){msg(e.message,true)}}
async function startTraining(datasetId){const target=$(`#target-${CSS.escape(datasetId)}`).value;const config={epochs:100,hidden_layers:[64,32],seed:42};const textSelect=$(`#text-${CSS.escape(datasetId)}`);if(textSelect)config.text_column=textSelect.value;try{const {run}=await api(`/api/projects/${selected}/train`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataset_id:datasetId,target_column:target,config})});msg('Training run queued.');pollRun(run.id,datasetId)}catch(e){msg(e.message,true)}}
async function pollRun(runId,datasetId){try{const {run}=await api(`/api/runs/${runId}`);const box=$(`#run-${CSS.escape(datasetId)}`);if(!box)return;box.innerHTML=`<div class="notice">Run ${escapeHtml(run.status)}${run.error?`: ${escapeHtml(run.error)}`:''}</div>${run.result?`<pre style="white-space:pre-wrap;background:#f7f9fc;padding:12px;border-radius:7px">${escapeHtml(JSON.stringify(run.result.metrics,null,2))}</pre>`:''}`;if(run.status==='queued'||run.status==='running')setTimeout(()=>pollRun(runId,datasetId),1200)}catch(e){msg(e.message,true)}}
$('#create').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target);try{const {project}=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(form))});e.target.reset();await loadProjects();selectProject(project.id);msg('Project created.')}catch(err){msg(err.message,true)}});$('#refresh').onclick=loadProjects;
$('#register-toggle').onclick=()=>{registerMode=!registerMode;$('#auth-submit').textContent=registerMode?'Register':'Sign in';$('#register-toggle').textContent=registerMode?'Back to sign in':'Create account';document.querySelector('#auth-form [name=password]').autocomplete=registerMode?'new-password':'current-password'};
$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const mode=registerMode?'register':'login';try{const {user}=await api('/api/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(f))});currentUser=user;openWorkspace()}catch(err){$('#auth-message').innerHTML=`<div class="error">${escapeHtml(err.message)}</div>`}};
async function openWorkspace(){const me=await api('/api/auth/me');currentUser=me.user;if(!currentUser){$('#auth-panel').classList.remove('hidden');$('#app-content').classList.add('hidden');return}$('#auth-panel').classList.add('hidden');$('#app-content').classList.remove('hidden');document.querySelector('.top').innerHTML=`<div class="brand">Neural<span>Forge</span></div><div class="small">${escapeHtml(currentUser.username)} · ${escapeHtml(currentUser.role)} <button class="secondary" id="logout" style="margin-left:10px">Sign out</button></div>`;$('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});currentUser=null;selected=null;location.reload()};const adminPanel=$('#admin-global');if(currentUser.role==='admin'){adminPanel.classList.remove('hidden');api('/api/admin/config').then(({config})=>{if(config.application_name)$('#global-cfg-name').value=config.application_name;if(config.max_upload_bytes)$('#global-cfg-upload').value=Math.round(config.max_upload_bytes/1048576);$('#global-cfg-registration').checked=config.allow_registration!==false}).catch(e=>msg(e.message,true));$('#global-cfg-save').onclick=async()=>{try{const {config}=await api('/api/admin/config',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({application_name:$('#global-cfg-name').value,allow_registration:$('#global-cfg-registration').checked,max_upload_bytes:Number($('#global-cfg-upload').value)*1048576})});document.title=config.application_name||'NeuralForge';msg('Global settings saved.')}catch(e){msg(e.message,true)}}}else adminPanel.classList.add('hidden');await loadProjects()}
async function initialize(){try{const {user}=await api('/api/auth/me');currentUser=user;if(user)openWorkspace();else{$('#auth-panel').classList.remove('hidden');$('#app-content').classList.add('hidden')}}catch(e){msg(e.message,true)}}initialize();
</script></body></html>'''
